INSERT INTO property (id, host_id, city_id, type_id, policy_id, title, description, address, latitude, longitude, check_in_time, check_out_time, status) VALUES
 (18, 20, 23, 5, 1, 'اقامتگاه بوم‌گردی پونه کرمانشاه', 'اقامتگاه بوم‌گردی با اتاق‌های خانوادگی و غذای محلی دست‌پخت خانواده میزبان. برنامه‌های گردشگری به کتیبه بیستون و طاق‌بستان با هماهنگی میزبان انجام می‌شود. آسمان شب، سکوت و مهمان‌نوازی محلی، ویژگی اصلی این اقامتگاه است.', 'کرمانشاه، کرمانشاه، محله قدیمی، کوچه یاس', 34.304906, 47.067234, '14:00', '11:00', 'active'),
 (19, 17, 1, 6, 2, 'هتل پارسیان آزادی', 'هتل پارسیان آزادی یکی از هتل‌های پنج‌ستاره تهران است با لابی مجلل، رستوران‌های ایرانی و بین‌المللی، استخر و مرکز سلامت. فاصله تا پل طبیعت حدود 15 دقیقه با خودرو است و بازار بزرگ تهران نیز در نزدیکی هتل قرار دارد. صبحانه بوفه و اینترنت پرسرعت رایگان است.', 'تهران، تهران، بلوار اصلی، جنب پل طبیعت', 35.729681, 51.308243, '14:00', '12:00', 'active'),
 (20, 17, 12, 6, 1, 'هتل جزیره قشم', 'هتلی تمیز و خوش‌موقعیت در قشم با پرسنل خوش‌برخورد و صبحانه ایرانی. دسترسی آسان به جنگل حرا و روستای لافت؛ مناسب سفرهای خانوادگی و کاری.', 'هرمزگان، قشم، خیابان شریعتی', 26.973406, 56.243606, '14:00', '12:00', 'active'),
 (21, 4, 3, 1, 2, 'ویلا مدرن دوخوابه در نوشهر', 'ویلای ویودار در نوشهر که برای اقامت خانوادگی کاملاً تجهیز شده است. حیاط با آلاچیق و باربیکیو، پارکینگ اختصاصی و فاصله 12 دقیقه‌ای تا جاده چالوس. برگزاری مهمانی و پخش موسیقی با صدای بلند مجاز نیست.', 'مازندران، نوشهر، بلوار خورشید', 36.637152, 51.467446, '14:00', '12:00', 'active'),
 (22, 27, 20, 4, 1, 'کلبه چوبی کوهستانی در سرعین', 'کلبه چوبی دنج در دل طبیعت سرعین با بخاری هیزمی و بالکن رو به منظره. مناسب زوج‌ها و خانواده‌های کوچک؛ تا تله‌کابین آلوارس 12 دقیقه راه است.', 'اردبیل، سرعین، جاده جنگلی، کلبه‌های خورشید', 38.169189, 48.055192, '14:00', '12:00', 'active'),
 (23, 27, 17, 1, 3, 'ویلا ویودار چهارخوابه در چالوس', 'ویلای ساحلی در چالوس که برای اقامت خانوادگی کاملاً تجهیز شده است. حیاط با آلاچیق و باربیکیو، پارکینگ اختصاصی و فاصله 15 دقیقه‌ای تا ساحل چالوس. برگزاری مهمانی و پخش موسیقی با صدای بلند مجاز نیست.', 'مازندران، چالوس، بلوار گلستان', 36.665165, 51.392936, '15:00', '12:00', 'active'),
 (24, 26, 16, 2, 2, 'سوئیت نوساز در امام رضا مشهد', 'سوئیت مبله و تمیز در محله طبرسی مشهد با دسترسی سریع به آرامگاه فردوسی و حمل‌ونقل عمومی. مناسب سفرهای کاری، درمانی و خانوادگی.', 'خراسان رضوی، مشهد، طبرسی', 36.316008, 59.607933, '14:00', '12:00', 'active'),
 (25, 16, 1, 6, 2, 'هتل پارسیان استقلال', 'هتل پارسیان استقلال یکی از هتل‌های پنج‌ستاره تهران است با لابی مجلل، رستوران‌های ایرانی و بین‌المللی، استخر و مرکز سلامت. فاصله تا کاخ گلستان حدود 10 دقیقه با خودرو است و دربند نیز در نزدیکی هتل قرار دارد. صبحانه بوفه و اینترنت پرسرعت رایگان است.', 'تهران، تهران، بلوار اصلی، جنب کاخ گلستان', 35.683347, 51.364782, '14:00', '12:00', 'draft'),
 (26, 2, 39, 1, 3, 'ویلا نوساز چهارخوابه در شهمیرزاد', 'ویلای ساحلی در شهمیرزاد که برای اقامت خانوادگی کاملاً تجهیز شده است. حیاط با آلاچیق و باربیکیو، پارکینگ اختصاصی و فاصله 7 دقیقه‌ای تا باغ‌های گردو. برگزاری مهمانی و پخش موسیقی با صدای بلند مجاز نیست.', 'سمنان، شهمیرزاد، شهرک پونه', 35.761617, 53.352531, '15:00', '12:00', 'active'),
 (27, 16, 16, 6, 2, 'هتل قصر طلایی', 'هتل قصر طلایی یکی از هتل‌های پنج‌ستاره مشهد است با لابی مجلل، رستوران‌های ایرانی و بین‌المللی، استخر و مرکز سلامت. فاصله تا کوهسنگی حدود 7 دقیقه با خودرو است و طرقبه و شاندیز نیز در نزدیکی هتل قرار دارد. صبحانه بوفه و اینترنت پرسرعت رایگان است.', 'خراسان رضوی، مشهد، بلوار اصلی، جنب کوهسنگی', 36.315703, 59.605468, '14:00', '12:00', 'active'),
 (28, 25, 28, 3, 1, 'آپارتمان مبله دوخوابه در گلشهر', 'آپارتمان مبله و تمیز در محله گلشهر بندرعباس با دسترسی سریع به بازار ماهی بندرعباس و حمل‌ونقل عمومی. مناسب سفرهای کاری، درمانی و خانوادگی.', 'هرمزگان، بندرعباس، گلشهر', 27.194378, 56.274282, '15:00', '12:00', 'active'),
 (29, 3, 14, 1, 2, 'ویلا حیاط‌دار چهارخوابه در بندر انزلی', 'ویلای دوبلکس در بندر انزلی که برای اقامت خانوادگی کاملاً تجهیز شده است. حیاط با آلاچیق و باربیکیو، پارکینگ اختصاصی و فاصله 12 دقیقه‌ای تا تالاب انزلی. برگزاری مهمانی و پخش موسیقی با صدای بلند مجاز نیست.', 'گیلان، بندر انزلی، شهرک بی‌بی', 37.48871, 49.488156, '14:00', '12:00', 'active'),
 (30, 20, 11, 7, 2, 'هتل‌آپارتمان ساحل کیش', 'هتل‌آپارتمان با واحدهای مبله و آشپزخانه مجهز، نزدیک ساحل مرجان. ترانسفر فرودگاه و استخر برای مهمانان رایگان است.', 'هرمزگان، کیش، نزدیک ساحل مرجان', 26.521861, 53.98888, '14:00', '12:00', 'active'),
 (31, 17, 16, 6, 2, 'هتل مدینة‌الرضا', 'هتل مدینة‌الرضا یکی از هتل‌های پنج‌ستاره مشهد است با لابی مجلل، رستوران‌های ایرانی و بین‌المللی، استخر و مرکز سلامت. فاصله تا آرامگاه فردوسی حدود 5 دقیقه با خودرو است و کوهسنگی نیز در نزدیکی هتل قرار دارد. صبحانه بوفه و اینترنت پرسرعت رایگان است.', 'خراسان رضوی، مشهد، بلوار اصلی، جنب آرامگاه فردوسی', 36.322699, 59.61874, '14:00', '12:00', 'active'),
 (32, 3, 10, 9, 2, 'هتل سنتی خانه‌های زندیه شیراز', 'خانه‌ای تاریخی با حیاط مرکزی، حوض فیروزه‌ای و ارسی‌های رنگی که به اقامتگاه سنتی تبدیل شده است. تا مسجد نصیرالملک 7 دقیقه پیاده راه است. صبحانه سنتی و چای در حیاط، تجربه‌ای اصیل از معماری ایرانی است.', 'فارس، شیراز، بافت تاریخی، نزدیک مسجد نصیرالملک', 29.627731, 52.516675, '14:00', '12:00', 'active'),
 (33, 20, 39, 1, 2, 'ویلا دوبلکس چهارخوابه در شهمیرزاد', 'ویلای حیاط‌دار در شهمیرزاد که برای اقامت خانوادگی کاملاً تجهیز شده است. حیاط با آلاچیق و باربیکیو، پارکینگ اختصاصی و فاصله 15 دقیقه‌ای تا جنگل ابر. برگزاری مهمانی و پخش موسیقی با صدای بلند مجاز نیست.', 'سمنان، شهمیرزاد، شهرک بهار', 35.778894, 53.354742, '15:00', '12:00', 'active'),
 (34, 6, 29, 5, 2, 'اقامتگاه بوم‌گردی ستاره چابهار', 'اقامتگاه بوم‌گردی با اتاق‌های کاهگلی و غذای محلی دست‌پخت خانواده میزبان. برنامه‌های گردشگری به ساحل دریای عمان و ساحل درک با هماهنگی میزبان انجام می‌شود. آسمان شب، سکوت و مهمان‌نوازی محلی، ویژگی اصلی این اقامتگاه است.', 'سیستان و بلوچستان، چابهار، محله قدیمی، کوچه انار', 25.310579, 60.613393, '15:00', '11:00', 'active'),
