INSERT INTO review (booking_id, rating, comment, created_at) VALUES
 (16, 4, 'نسبت به قیمت ارزش خرید خوبی داشت. صبحانه می‌توانست متنوع‌تر باشد.', '2026-01-11 11:00+03:30'),
